sys_script_include.script:
var LocalPolicyProvider = Class.create();
LocalPolicyProvider.prototype = {

    initialize: function () {
        this.serializer = new AggregateSerializer();
    },

    // PolicyProvider contract ------------------------------------------------
    // ref: policy sys_id, policy_number or external_ref.
    getPolicy: function (ref) {
        var gr = new GlideRecord(Constants.TABLE.POLICY);
        if (gr.get(ref))
            return gr;
        var q = new GlideRecord(Constants.TABLE.POLICY);
        q.addQuery('policy_number', ref).addOrCondition('external_ref', ref);
        q.setLimit(1);
        q.query();
        return q.next() ? q : null;
    },

    getCurrentTerm: function (policyId) {
        var p = this.getPolicy(policyId);
        if (p && p.getValue('current_term'))
            return this._get(Constants.TABLE.POLICY_TERM, p.getValue('current_term'));
        var t = new GlideRecord(Constants.TABLE.POLICY_TERM);
        t.addQuery('policy', p ? p.getUniqueValue() : policyId);
        t.orderByDesc('term_number');
        t.setLimit(1);
        t.query();
        return t.next() ? t : null;
    },

    // Current version of the policy, or the version in force on asOfDate (yyyy-mm-dd).
    getCurrentVersion: function (policyId, asOfDate) {
        var p = this.getPolicy(policyId);
        if (!p)
            return null;
        if (!asOfDate && p.getValue('current_version'))
            return this._get(Constants.TABLE.POLICY_VERSION, p.getValue('current_version'));
        var v = new GlideRecord(Constants.TABLE.POLICY_VERSION);
        v.addQuery('policy', p.getUniqueValue());
        v.addQuery('status', 'IN', [Constants.CHOICE.POLICY_VERSION_STATUS.ISSUED, Constants.CHOICE.POLICY_VERSION_STATUS.SUPERSEDED].join(','));
        if (asOfDate)
            v.addQuery('transaction_effective_date', '<=', asOfDate);
        v.orderByDesc('transaction_effective_date');
        v.orderByDesc('version_number');
        v.setLimit(1);
        v.query();
        return v.next() ? v : null;
    },

    getVersionSnapshot: function (versionId) {
        return this.serializer.serialize('policy_version', versionId);
    },

    isExternal: function (policyId) {
        var p = this.getPolicy(policyId);
        return !!p && p.getValue('system_of_record') === Constants.CHOICE.SYSTEM_OF_RECORD.EXTERNAL;
    },

    _get: function (table, id) {
        var gr = new GlideRecord(table);
        return gr.get(id) ? gr : null;
    },

    type: 'LocalPolicyProvider'
};
